def resource_title(key, locale, slug, fallback):
    if key != "lumibopomofo" or locale not in {"fr-CA", "fr-FR", "pt-PT"}:
        return fallback
    if slug not in TITLES:
        raise ValueError(f"Unreviewed Bopomofo title: {locale}/{slug}")
    return TITLES[slug][1 if locale == "pt-PT" else 0]
